use vstd::prelude::*;

verus! {
    /// Broadcast two non‐empty, shape‐compatible vectors of i8 to a common length.
    ///
    /// The inputs must satisfy one of:
    ///   - They have the same length, or
    ///   - At least one has length 1.
    ///
    /// The outputs both have length L = max(a.len(), b.len()), and for each index i < L:
    ///   - If a.len() == 1 then a_out[i] == a[0], else a_out[i] == a[i].
    ///   - If b.len() == 1 then b_out[i] == b[0], else b_out[i] == b[i].
    fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (a_out: Vec<i8>, b_out: Vec<i8>)
        requires
            // non‐empty
            a.len() >= 1,
            b.len() >= 1,
            // compatibility: same length or one of them has length 1
            a.len() == b.len() || a.len() == 1 || b.len() == 1,
        ensures
            let m = a.len();
            let n = b.len();
            let L = if m > n { m } else { n };
            // outputs both of length L
            a_out.len() == L &&
            b_out.len() == L &&
            // broadcasting semantics holds pointwise
            forall |i: usize| i < L ==>
                (if m == 1 { a.get(0).unwrap() } else { a.get(i).unwrap() }) 
                    == &*a_out.get(i).unwrap() &&
                (if n == 1 { b.get(0).unwrap() } else { b.get(i).unwrap() }) 
                    == &*b_out.get(i).unwrap(),
    {
        let m = a.len();
        let n = b.len();
        let L = if m > n { m } else { n };

        // prepare result vectors
        let mut a_out = Vec::<i8>::with_capacity(L);
        let mut b_out = Vec::<i8>::with_capacity(L);

        let mut idx: usize = 0;
        while idx < L
            invariant
                idx <= L,
                a_out.len() == idx,
                b_out.len() == idx,
                // partial correctness up to idx
                forall |j: usize| j < idx ==>
                    (if m == 1 { *a.get(0).unwrap() } else { *a.get(j).unwrap() })
                        == *a_out.get(j).unwrap() &&
                    (if n == 1 { *b.get(0).unwrap() } else { *b.get(j).unwrap() })
                        == *b_out.get(j).unwrap(),
            decreases L - idx,
        {
            // fetch or repeat a‐value
            let va: i8 = if m == 1 {
                *a.get(0).unwrap()
            } else {
                // since m > 1 and idx < L = m, idx < m
                assert(idx < m);
                *a.get(idx).unwrap()
            };
            // fetch or repeat b‐value
            let vb: i8 = if n == 1 {
                *b.get(0).unwrap()
            } else {
                // since n > 1 and idx < L = n, idx < n
                assert(idx < n);
                *b.get(idx).unwrap()
            };
            a_out.push(va);
            b_out.push(vb);
            idx += 1;
        }

        (a_out, b_out)
    }
}

fn main() {
    // Example usage (not verified):
    let a = Vec::from_slice(&[42]);
    let b = Vec::from_slice(&[1,2,3]);
    let (a_brd, b_brd) = broadcast_arrays(a, b);
    assert(a_brd == Vec::from_slice(&[42,42,42]));
    assert(b_brd == Vec::from_slice(&[1,2,3]));
}